      function appDialog({ title = "TechGen1o1", message = "", mode = "alert", inputType = "text", defaultValue = "", confirmText = "OK", cancelText = "Cancel" } = {}) {
        return new Promise((resolve) => {
          const backdrop = document.createElement("div");
          backdrop.className = "app-dialog-backdrop";
          backdrop.setAttribute("role", "presentation");

          const dialog = document.createElement("div");
          dialog.className = "app-dialog";
          dialog.setAttribute("role", "dialog");
          dialog.setAttribute("aria-modal", "true");

          const heading = document.createElement("h3");
          heading.textContent = title;

          const copy = document.createElement("p");
          copy.textContent = message;

          dialog.appendChild(heading);
          dialog.appendChild(copy);

          let input = null;
          if (mode === "prompt") {
            input = document.createElement("input");
            input.className = "app-dialog-input";
            input.type = inputType === "password" ? "password" : "text";
            input.value = String(defaultValue ?? "");
            input.autocomplete = input.type === "password" ? "current-password" : "off";
            dialog.appendChild(input);
          }

          const actions = document.createElement("div");
          actions.className = "app-dialog-actions";

          if (mode !== "alert") {
            const cancel = document.createElement("button");
            cancel.type = "button";
            cancel.className = "button secondary";
            cancel.textContent = cancelText;
            cancel.addEventListener("click", () => finish(mode === "prompt" ? null : false));
            actions.appendChild(cancel);
          }

          const confirm = document.createElement("button");
          confirm.type = "button";
          confirm.className = mode === "confirm" ? "button danger" : "button";
          confirm.textContent = confirmText;
          confirm.addEventListener("click", () => finish(mode === "prompt" ? input.value : true));
          actions.appendChild(confirm);
          dialog.appendChild(actions);
          backdrop.appendChild(dialog);
          document.body.appendChild(backdrop);

          const previousActive = document.activeElement;
          const keyHandler = (event) => {
            if (event.key === "Escape" && mode !== "alert") {
              event.preventDefault();
              finish(mode === "prompt" ? null : false);
            } else if (event.key === "Enter" && mode === "prompt" && document.activeElement === input) {
              event.preventDefault();
              finish(input.value);
            }
          };
          document.addEventListener("keydown", keyHandler, true);

          function finish(value) {
            document.removeEventListener("keydown", keyHandler, true);
            backdrop.remove();
            if (previousActive && typeof previousActive.focus === "function") setTimeout(() => previousActive.focus(), 0);
            resolve(value);
          }

          requestAnimationFrame(() => {
            if (input) { input.focus(); input.select(); } else confirm.focus();
          });
        });
      }

      function appPrompt(message, defaultValue = "", options = {}) {
        return appDialog({ title: options.title || "TechGen1o1", message, mode: "prompt", inputType: options.inputType || "text", defaultValue, confirmText: options.confirmText || "Continue", cancelText: options.cancelText || "Cancel" });
      }
