      async function sha256Hex(value) {
        const bytes = new TextEncoder().encode(value);
        const digest = await crypto.subtle.digest("SHA-256", bytes);
        return Array.from(new Uint8Array(digest), (byte) => byte.toString(16).padStart(2, "0")).join("");
      }

      function safeLocalSet(key, value) {
        try { localStorage.setItem(key, value); return true; }
        catch { return false; }
      }
      function safeLocalRemove(key) {
        try { localStorage.removeItem(key); return true; }
        catch { return false; }
      }
      function saveActiveSession() {
        if (!currentUser || !sessionLastActivity) return safeLocalRemove(SESSION_KEY);
        return safeLocalSet(SESSION_KEY, JSON.stringify({ username: currentUser, lastActivity: sessionLastActivity }));
      }
      function restoreActiveSession() {
        try {
          const saved = JSON.parse(localStorage.getItem(SESSION_KEY) || "null");
          if (!saved || !saved.username) return false;
          const lastActivity = Number(saved.lastActivity) || 0;
          if (!lastActivity || Date.now() - lastActivity >= SESSION_TIMEOUT_MS) { safeLocalRemove(SESSION_KEY); return false; }
          const account = accounts.find((entry) => entry.username === String(saved.username).toLowerCase() && entry.active !== false);
          if (!account) { safeLocalRemove(SESSION_KEY); return false; }
          showApp(account);
          return true;
        } catch {
          safeLocalRemove(SESSION_KEY);
          return false;
        }
      }
      function openLocalDatabase() {
        if (!window.indexedDB) return Promise.resolve(null);
        if (databaseHandle) return Promise.resolve(databaseHandle);
        return new Promise((resolve) => {
          const request = indexedDB.open(DB_NAME, DB_VERSION);
          request.onupgradeneeded = () => {
            const db = request.result;
            if (!db.objectStoreNames.contains(DB_STORE)) db.createObjectStore(DB_STORE);
          };
          request.onsuccess = () => {
            databaseHandle = request.result;
            databaseHandle.onversionchange = () => { databaseHandle.close(); databaseHandle = null; };
            resolve(databaseHandle);
          };
          request.onerror = () => resolve(null);
          request.onblocked = () => resolve(null);
        });
      }
      function databaseGet(db, key) {
        return new Promise((resolve) => {
          try {
            const request = db.transaction(DB_STORE, "readonly").objectStore(DB_STORE).get(key);
            request.onsuccess = () => resolve(request.result || null);
            request.onerror = () => resolve(null);
          } catch { resolve(null); }
        });
      }
      function databasePut(db, key, value) {
        return new Promise((resolve) => {
          try {
            const transaction = db.transaction(DB_STORE, "readwrite");
            transaction.objectStore(DB_STORE).put(value, key);
            transaction.oncomplete = () => resolve(true);
            transaction.onerror = () => resolve(false);
            transaction.onabort = () => resolve(false);
          } catch { resolve(false); }
        });
      }
      function databaseSnapshot() {
        return {
          schemaVersion: 2,
          savedAt: new Date().toISOString(),
          items,
          activities,
          transactions,
          personnel,
          attendance,
          accounts,
          auditEvents,
          backupLogs,
          loginSecurity,
          securityEvents,
          recoveryHash: recoveryHash(),
          ownerPhone: readOwnerPhone(),
        };
      }
      function cacheDatabaseState() {
        safeLocalSet(STORAGE_KEY, JSON.stringify(items));
        safeLocalSet(ACTIVITY_KEY, JSON.stringify(activities));
        safeLocalSet(TRANSACTIONS_KEY, JSON.stringify(transactions));
        safeLocalSet(PERSONNEL_KEY, JSON.stringify(personnel));
        safeLocalSet(ATTENDANCE_KEY, JSON.stringify(attendance.slice(0, 5000)));
        safeLocalSet(ACCOUNTS_KEY, JSON.stringify(accounts));
        safeLocalSet(AUDIT_KEY, JSON.stringify(auditEvents.slice(0, 1000)));
        safeLocalSet(BACKUP_LOG_KEY, JSON.stringify(backupLogs.slice(0, 100)));
        safeLocalSet(SECURITY_KEY, JSON.stringify(loginSecurity));
        safeLocalSet(SECURITY_LOG_KEY, JSON.stringify(securityEvents.slice(0, 100)));
      }
      function applyDatabaseState(state) {
        if (!state || typeof state !== "object") return;
        if (Array.isArray(state.items)) items = state.items.map(normalizeItem).filter(Boolean);
        if (Array.isArray(state.activities)) activities = state.activities.filter((entry) => entry && typeof entry === "object" && entry.createdAt);
        if (Array.isArray(state.transactions)) transactions = normalizeTransactions(state.transactions);
        if (Array.isArray(state.personnel)) personnel = validRestoredPersonnel(state.personnel);
        if (Array.isArray(state.attendance)) attendance = state.attendance.filter((entry) => entry && typeof entry === "object" && entry.personId && ["login", "logout"].includes(entry.action) && entry.timestamp);
        if (Array.isArray(state.accounts)) {
          const restored = normalizeAccounts(state.accounts);
          if (restored.some((account) => account.role === "admin")) accounts = restored;
        }
        if (Array.isArray(state.auditEvents)) auditEvents = validRestoredAuditEvents(state.auditEvents);
        if (Array.isArray(state.backupLogs)) backupLogs = state.backupLogs.filter((entry) => entry && typeof entry === "object").slice(0, 100);
        if (state.loginSecurity && typeof state.loginSecurity === "object") loginSecurity = { failedAttempts: Math.min(LOGIN_MAX_ATTEMPTS, Math.max(0, Math.trunc(Number(state.loginSecurity.failedAttempts) || 0))), lastFailedAt: Number(state.loginSecurity.lastFailedAt) || 0, lockedUntil: Number(state.loginSecurity.lockedUntil) || 0 };
        if (Array.isArray(state.securityEvents)) securityEvents = validRestoredSecurityEvents(state.securityEvents);
        if (/^[a-f0-9]{64}$/i.test(String(state.recoveryHash || ""))) safeLocalSet(RECOVERY_HASH_KEY, String(state.recoveryHash).toLowerCase());
        if (Object.prototype.hasOwnProperty.call(state, "ownerPhone")) safeLocalSet(OWNER_PHONE_KEY, normalizeOwnerPhone(state.ownerPhone));
        cacheDatabaseState();
      }
      async function hydrateDatabase() {
        databaseHydrating = true;
        const db = await openLocalDatabase();
        if (!db) { databaseHydrating = false; return false; }
        const saved = await databaseGet(db, DB_STATE_KEY);
        const localRevision = Number(localStorage.getItem(DB_LOCAL_REVISION_KEY)) || 0;
        const databaseRevision = saved ? Date.parse(saved.savedAt || "") || 0 : 0;
        if (saved && databaseRevision >= localRevision) applyDatabaseState(saved);
        else await databasePut(db, DB_STATE_KEY, databaseSnapshot());
        databaseHydrating = false;
        migrateLegacyTransactions();
        cacheDatabaseState();
        render();
        return true;
      }
      function scheduleDatabaseWrite() {
        if (databaseHydrating) return;
        safeLocalSet(DB_LOCAL_REVISION_KEY, String(Date.now()));
        clearTimeout(databaseWriteTimer);
        databaseWriteTimer = setTimeout(async () => {
          const db = await openLocalDatabase();
          if (!db) return;
          const saved = await databasePut(db, DB_STATE_KEY, databaseSnapshot());
          if (saved) safeLocalSet(DB_SYNC_KEY, String(Date.now()));
        }, 25);
      }

