        Object.entries({sku:item.sku,barcode:item.barcode,name:item.name,category:item.category,brand:item.brand,model:item.model,condition:item.condition || "New",quantity:item.quantity,reorderLevel:item.reorderLevel,unit:item.unit,actualPrice:item.actualPrice,sellingPrice:item.sellingPrice,lastPrice:item.lastPrice,supplier:item.supplier,location:item.location,serialNumber:item.serialNumber,purchaseDate:item.purchaseDate,warrantyUntil:item.warrantyUntil,description:item.description}).forEach(([key,value]) => setFormValue(key,value));
